import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) {
            all.append(line).append(' ');
        }
        StringTokenizer tok = new StringTokenizer(all.toString());

        int S = Integer.parseInt(tok.nextToken());
        int T = Integer.parseInt(tok.nextToken());
        int P = Integer.parseInt(tok.nextToken());

        int[] h = new int[S + 1];
        for (int i = 1; i <= S; i++) {
            h[i] = Integer.parseInt(tok.nextToken());
        }

        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i <= S; i++) adj.add(new ArrayList<>());

        // Um túnel (i, j) só pode ser usado no sentido de maior altura para menor altura
        for (int t = 0; t < T; t++) {
            int i = Integer.parseInt(tok.nextToken());
            int j = Integer.parseInt(tok.nextToken());
            if (h[i] > h[j]) {
                adj.get(i).add(j);
            } else if (h[j] > h[i]) {
                adj.get(j).add(i);
            }
        }

        // BFS a partir de P contando salões alcançáveis (excluindo P)
        boolean[] vis = new boolean[S + 1];
        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(P);
        vis[P] = true;
        int count = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj.get(u)) {
                if (!vis[v]) {
                    vis[v] = true;
                    count++;
                    q.add(v);
                }
            }
        }

        System.out.println(count);
    }
}
